export class PoolRow {
  readonly pool = input.required<Pool>();
  /** Everyone on the sheet, retired included, as the people list now shows them. */
  readonly people = input.required<Person[]>();

  protected readonly pools = inject(Pools);
  private readonly byId = computed(() => new Map(this.people().map((p) => [p.id, p])));

  /** The members' shares added up, a retired member's counting as given and one out of force left out. */
  private readonly totalCents = computed(() =>
    this.pool().members.reduce(
      (sum, m) => (!m.inForce ? sum : sum + (shareCents(m.share) ?? 0)), 0),
  );
  protected readonly totalShare = computed(() => formatCents(this.totalCents()));
  protected readonly balanced = computed(() => this.totalCents() === 10000);

  protected readonly error = signal('');
  protected readonly form = new FormGroup({
    personId: new FormControl('', { nonNullable: true }),
    share: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });
  private submitting = false;

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  /** The member's key in its data-testid: the person's id, or pool-<name> for a pool. */
  protected memberKey(m: PoolMember): string {
    return m.personId === null ? `pool-${m.name}` : String(m.personId);
  }

  protected nameOf(m: PoolMember): string {
    return m.personId === null ? `pool:${m.name}` : (this.byId().get(m.personId)?.name ?? m.name);
  }

  protected isRetired(m: PoolMember): boolean {
    return m.personId !== null && (this.byId().get(m.personId)?.retired ?? m.retired);
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const { personId, share, from, to } = this.form.getRawValue();
    const poolId = personId.startsWith('pool:') ? Number(personId.slice(5)) : null;
    const id = Number(personId);
    if (poolId === null ? personId === '' || !this.byId().has(id) : !this.pools.list().some((p) => p.id === poolId)) {
      this.error.set('Choose a person or a pool.');
      return;
    }
    if (shareCents(share) === null) {
      this.error.set('A share is a percent with two decimals, more than 0.00 and at most 100.00.');
      return;
    }
    if (from && to && to < from) {
      this.error.set('The to-date is before the from-date.');
      return;
    }
    if (poolId === null && this.pool().members.some((m) => m.personId === id)) {
      this.error.set('That person is already in the pool.');
      return;
    }
    this.submitting = true;
    try {
      await this.pools.addMember(this.pool().id, poolId === null ? { personId: id } : { poolId }, share.trim(),
        { from: from || null, to: to || null });
      this.form.reset({ personId: '', share: '', from: '', to: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 409
          ? poolId === null
            ? 'That person is already in the pool, or the sheet may not be changed.'
            : 'That pool is already a member of a pool, would contain itself, or would make a chain of '
              + 'pools more than three deep; or the sheet may not be changed.'
          : e instanceof HttpErrorResponse && e.status === 400
            ? 'The share or the dates are not valid.'
          : e instanceof HttpErrorResponse && e.status === 403
            ? 'A viewer may not add a pool member.'
            : 'The member could not be added.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

/** A member of a pool: a person of the sheet, or another pool of it, and their share percent (two
 *  decimals). */
export interface PoolMember {
  /** The person; null when the member is a pool. */
  personId: number | null;
  /** The pool; null when the member is a person. */
  poolId: number | null;
  name: string;
  share: string;
  /** Whether the person has a retirement day set, whatever the day: they then get no
   *  cut, their share spread over the other members. */
  retired: boolean;
  /** Their cut of the pool's pot, as text with two decimals; null when the pool shows no cut (it is
   *  not balanced, or it has no pot). */
  cut: string | null;
  /** The first day of the membership (yyyy-mm-dd); null: no start. */
  from: string | null;
  /** The last day of the membership (yyyy-mm-dd); null: no end. */
  to: string | null;
  /** Whether the membership's dates include the sheet's today: a member out of force is left out
   *  entirely (not in the total share, not in the balance, no cut). */
  inForce: boolean;
}

/** A pool on the sheet: its members in the order they were added, their shares' total and whether
 *  it is exactly 100.00. */
export interface Pool {
  id: number;
  name: string;
  members: PoolMember[];
  totalShare: string;
  balanced: boolean;
}

/** A share as entered: a number with at most two decimals. */
const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

/** A share as entered in hundredths, when it has at most two decimals and is above 0.00 and at
 *  most 100.00; null otherwise. */
export function shareCents(text: string): number | null {
  const t = text.trim();
  if (!SHARE.test(t)) return null;
  const [whole, frac = ''] = t.split('.');
  const cents = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  return cents > 0 && cents <= 10000 ? cents : null;
}

/** Hundredths as text with two decimals. */
export function formatCents(cents: number): string {
  return `${Math.trunc(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

// The pools of the active sheet, re-read whenever the sheet is loaded.
@Injectable({ providedIn: 'root' })
export class Pools {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's pools in the order they were added. */
  readonly list = signal<Pool[]>([]);
  private reads = 0;

  constructor() {
    effect(() => {
      this.session.loads();
      const sheetId = this.session.sheetId();
      this.list.set([]);
      if (sheetId) void this.reload(sheetId);
    });
  }

  /** Read the active sheet's pools again (the pot they cut has changed). */
  refresh(): void {
    const sheetId = this.session.sheetId();
    if (sheetId) void this.reload(sheetId);
  }

  /** Add a pool; refused (400) when the name is blank and (409) when it is already a pool. */
  async add(name: string): Promise<Pool> {
    const { sheetId, user } = this.active();
    const saved = await firstValueFrom(
      this.http.post<Pool>(this.url(sheetId), { name }, { headers: { 'X-User': user } }),
    );
    this.keep(saved);
    return saved;
  }

  /** Add a person, or another pool, to a pool with a share; refused (400) for a bad share and (409)
   *  when the person is already in the pool, or the pool is already a member of a pool, would contain
   *  itself or would make a chain of pools too deep; the optional from- and to-dates bound the days
   *  the membership runs (refused, 400, when the to-date is before the from-date). */
  async addMember(
    poolId: number,
    member: { personId: number } | { poolId: number },
    share: string,
    dates: { from: string | null; to: string | null },
  ): Promise<void> {
    const { sheetId, user } = this.active();
    await firstValueFrom(
      this.http.post<Pool>(`${this.url(sheetId)}/${poolId}/members`, { ...member, share, ...dates },
        { headers: { 'X-User': user } }),
    );
    // a pool member changes the pots of the pools below it: read them all again
    await this.reload(sheetId);
  }

  private keep(saved: Pool): void {
    this.list.update((ps) =>
      ps.some((p) => p.id === saved.id) ? ps.map((p) => (p.id === saved.id ? saved : p)) : [...ps, saved],
    );
  }

  private async reload(sheetId: string): Promise<void> {
    const read = ++this.reads;
    try {
      const pools = await firstValueFrom(this.http.get<Pool[]>(this.url(sheetId)));
      if (read === this.reads) this.list.set(pools);
    } catch {
      // the list stays empty; the next load reads it again
    }
  }

  private active(): { sheetId: string; user: string } {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return { sheetId, user };
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/pools`;
  }
}
